let boxCount = msg.payload[1];

msg.topic = "registers";

msg.payload = {
    boxCount: boxCount
};

return msg;

msg.topic = "coils";

msg.payload = {
    motorRun: msg.payload[6]
};

return msg;

msg.payload = {
    machineRunning: msg.payload.coils.motorRun,
    boxCount: msg.payload.registers.boxCount
};

return msg;

const regs = msg.payload;

if (!Array.isArray(regs) || regs.length < 2) {
    node.warn("Expected two Modbus registers");
    return null;
}

const buf = Buffer.alloc(4);
buf.writeUInt16BE(regs[0], 0);
buf.writeUInt16BE(regs[1], 2);

msg.payload = buf.readFloatBE(0);
msg.topic = "speed_test_decoded";

return msg;

const topicMap = {
    "factory/conveyor/01/commands/start": 0,
    "factory/conveyor/01/commands/stop": 1,
    "factory/conveyor/01/sensors/entry": 4,
    "factory/conveyor/01/sensors/exit": 5
};

const address = topicMap[msg.topic];

if (address === undefined) {
    return null;
}

const value = typeof msg.payload === "string"
    ? msg.payload.toLowerCase() === "true"
    : Boolean(msg.payload);

msg.payload = {
    value: value,
    fc: 5,
    unitid: 1,
    address: address,
    quantity: 1
};
node.warn(`Topic=${msg.topic}, address=${address}, value=${value}`);
return msg;

const speed = Number(msg.payload);

if (!Number.isFinite(speed) || speed < 0 || speed > 1.33) {
    node.warn("Speed setpoint must be between 0 and 1.33");
    return null;
}

// Encode IEEE-754 REAL as two 16-bit registers,
// high word first, matching the OpenPLC mapping.
const buf = Buffer.alloc(4);
buf.writeFloatBE(speed, 0);

const highWord = buf.readUInt16BE(0);
const lowWord = buf.readUInt16BE(2);

msg.payload = {
    value: [highWord, lowWord],
    fc: 16,
    unitid: 1,
    address: 42,
    quantity: 2
};

return msg;

const topic = msg.topic;
const value = Number(msg.payload);

if (!Number.isFinite(value)) {
    node.warn(`Invalid numeric payload: ${msg.payload}`);
        return null;
        }

        // OpenPLC %MD addresses mapped to Modbus holding-register offsets.
        // Each REAL occupies two consecutive 16-bit registers.
        const addressMap = {
            // Scalar REAL variables
                load: {
                        variable: "ConveyorLoad",
                                address: 74
                                    },
                                        motorCurrent: {
                                                variable: "MotorCurrent",
                                                        address: 66
                                                            },

                                                                // Bearing temperature array: BearingTemperature[1..4]
                                                                    "ROLLER-1/BEARING-1/temperature": {
                                                                            variable: "BearingTemperature",
                                                                                    index: 1,
                                                                                            address: 2
                                                                                                },
                                                                                                    "ROLLER-1/BEARING-2/temperature": {
                                                                                                            variable: "BearingTemperature",
                                                                                                                    index: 2,
                                                                                                                            address: 4
                                                                                                                                },
                                                                                                                                    "ROLLER-2/BEARING-1/temperature": {
                                                                                                                                            variable: "BearingTemperature",
                                                                                                                                                    index: 3,
                                                                                                                                                            address: 6
                                                                                                                                                                },
                                                                                                                                                                    "ROLLER-2/BEARING-2/temperature": {
                                                                                                                                                                            variable: "BearingTemperature",
                                                                                                                                                                                    index: 4,
                                                                                                                                                                                            address: 8
                                                                                                                                                                                                },

                                                                                                                                                                                                    // Bearing vibration array: BearingVibration[1..4]
                                                                                                                                                                                                        "ROLLER-1/BEARING-1/vibration": {
                                                                                                                                                                                                                variable: "BearingVibration",
                                                                                                                                                                                                                        index: 1,
                                                                                                                                                                                                                                address: 18
                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                        "ROLLER-1/BEARING-2/vibration": {
                                                                                                                                                                                                                                                variable: "BearingVibration",
                                                                                                                                                                                                                                                        index: 2,
                                                                                                                                                                                                                                                                address: 20
                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                        "ROLLER-2/BEARING-1/vibration": {
                                                                                                                                                                                                                                                                                variable: "BearingVibration",
                                                                                                                                                                                                                                                                                        index: 3,
                                                                                                                                                                                                                                                                                                address: 22
                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                        "ROLLER-2/BEARING-2/vibration": {
                                                                                                                                                                                                                                                                                                                variable: "BearingVibration",
                                                                                                                                                                                                                                                                                                                        index: 4,
                                                                                                                                                                                                                                                                                                                                address: 24
                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                    // Resolve the MQTT topic to a PLC variable and register address.
                                                                                                                                                                                                                                                                                                                                    let mapping = null;

                                                                                                                                                                                                                                                                                                                                    if (topic.endsWith("/load")) {
                                                                                                                                                                                                                                                                                                                                        mapping = addressMap.load;
                                                                                                                                                                                                                                                                                                                                        } else if (topic.endsWith("/motorCurrent")) {
                                                                                                                                                                                                                                                                                                                                            mapping = addressMap.motorCurrent;
                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                for (const [suffix, config] of Object.entries(addressMap)) {
                                                                                                                                                                                                                                                                                                                                                        if (
                                                                                                                                                                                                                                                                                                                                                                    suffix.includes("/") &&
                                                                                                                                                                                                                                                                                                                                                                                topic.endsWith("/telemetry/" + suffix)
                                                                                                                                                                                                                                                                                                                                                                                        ) {
                                                                                                                                                                                                                                                                                                                                                                                                    mapping = config;
                                                                                                                                                                                                                                                                                                                                                                                                                break;
                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                            if (!mapping) {
                                                                                                                                                                                                                                                                                                                                                                                                                                node.warn(`Unrecognized telemetry topic: ${topic}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                    return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                    // Encode the REAL value as two 16-bit words.
                                                                                                                                                                                                                                                                                                                                                                                                                                    // High word first; reverse the order if your PLC mapping requires it.
                                                                                                                                                                                                                                                                                                                                                                                                                                    const buffer = Buffer.alloc(4);
                                                                                                                                                                                                                                                                                                                                                                                                                                    buffer.writeFloatBE(value, 0);

                                                                                                                                                                                                                                                                                                                                                                                                                                    const highWord = buffer.readUInt16BE(0);
                                                                                                                                                                                                                                                                                                                                                                                                                                    const lowWord = buffer.readUInt16BE(2);

                                                                                                                                                                                                                                                                                                                                                                                                                                    // Keep metadata available for debugging.
                                                                                                                                                                                                                                                                                                                                                                                                                                    msg.plcVariable = mapping.variable;
                                                                                                                                                                                                                                                                                                                                                                                                                                    msg.arrayIndex = mapping.index ?? null;
                                                                                                                                                                                                                                                                                                                                                                                                                                    msg.value = value;

                                                                                                                                                                                                                                                                                                                                                                                                                                    // Modbus Flex Write request: FC16, write two holding registers.
                                                                                                                                                                                                                                                                                                                                                                                                                                    msg.payload = {
                                                                                                                                                                                                                                                                                                                                                                                                                                        fc: 16,
                                                                                                                                                                                                                                                                                                                                                                                                                                            unitid: 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                address: mapping.address,
                                                                                                                                                                                                                                                                                                                                                                                                                                                    quantity: 2,
                                                                                                                                                                                                                                                                                                                                                                                                                                                        value: [highWord, lowWord]
                                                                                                                                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                                                                                                                                        return msg;

const prefix = "ns=2;s=[default]/";

// Map each OPC UA tag to its JSON destination.
const tagMap = {
    commandedSpeed: ["conveyor", "commandedSpeed"],
    conveyorLoad: ["conveyor", "conveyorLoad"],
    isMotorRunning: ["conveyor", "isMotorRunning"],
    motorCurrent: ["conveyor", "motorCurrent"],

    roller_1_bearing_1_temp: ["bearings", "roller_1_bearing_1", "temperature"],
    roller_1_bearing_1_vibration: ["bearings", "roller_1_bearing_1", "vibration"],
    roller_1_bearing_2_temp: ["bearings", "roller_1_bearing_2", "temperature"],
    roller_1_bearing_2_vibration: ["bearings", "roller_1_bearing_2", "vibration"],

    roller_2_bearing_1_temp: ["bearings", "roller_2_bearing_1", "temperature"],
    roller_2_bearing_1_vibration: ["bearings", "roller_2_bearing_1", "vibration"],
    roller_2_bearing_2_temp: ["bearings", "roller_2_bearing_2", "temperature"],
    roller_2_bearing_2_vibration: ["bearings", "roller_2_bearing_2", "vibration"]
};

let values = flow.get("conveyorTagValues") || {};

// OPC UA update: extract and store the latest value.
if (typeof msg.topic === "string" && msg.topic.startsWith(prefix)) {
    const tagName = msg.topic.slice(prefix.length);

    if (tagMap[tagName]) {
        values[tagName] = msg.payload.value.value;
        flow.set("conveyorTagValues", values);
    }

    return null;
}

// Snapshot trigger: emit a complete JSON object every second.
if (msg.topic !== "build_timestamp") {
    return null;
}

const snapshot = {
    timestamp: new Date().toISOString(),
    conveyor: {},
    bearings: {
        roller_1_bearing_1: {},
        roller_1_bearing_2: {},
        roller_2_bearing_1: {},
        roller_2_bearing_2: {}
    }
};

for (const [tagName, path] of Object.entries(tagMap)) {
    if (!(tagName in values)) continue;

    let target = snapshot;
    for (let i = 0; i < path.length - 1; i++) {
        target = target[path[i]];
    }

    target[path[path.length - 1]] = values[tagName];
}

msg.topic = "factory/conveyor/01/scada_snapshot";
msg.payload = snapshot;

return msg;

msg.topic = "multiple";
msg.action = "subscribe";

msg.payload = [
    { nodeId: "ns=2;s=[default]/commandedSpeed" },
    { nodeId: "ns=2;s=[default]/conveyorLoad" },
    { nodeId: "ns=2;s=[default]/isMotorRunning" },
    { nodeId: "ns=2;s=[default]/motorCurrent" },

    { nodeId: "ns=2;s=[default]/roller_1_bearing_1_temp" },
    { nodeId: "ns=2;s=[default]/roller_1_bearing_1_vibration" },
    { nodeId: "ns=2;s=[default]/roller_1_bearing_2_temp" },
    { nodeId: "ns=2;s=[default]/roller_1_bearing_2_vibration" },

    { nodeId: "ns=2;s=[default]/roller_2_bearing_1_temp" },
    { nodeId: "ns=2;s=[default]/roller_2_bearing_1_vibration" },
    { nodeId: "ns=2;s=[default]/roller_2_bearing_2_temp" },
    { nodeId: "ns=2;s=[default]/roller_2_bearing_2_vibration" }
];

return msg;
